CREATE TABLE IF NOT EXISTS availability_blocks (id BIGINT AUTO_INCREMENT PRIMARY KEY, professional_id BIGINT NOT NULL, location_id SMALLINT NOT NULL, available_date DATE NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_availability_prof_date (professional_id,available_date,start_time));
CREATE TABLE IF NOT EXISTS professional_slots (id BIGINT AUTO_INCREMENT PRIMARY KEY, availability_block_id BIGINT NOT NULL, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, appointment_id BIGINT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_block_slot (availability_block_id,start_at));
